import pandas as pd
from sklearn.preprocessing import StandardScaler

def task_func(df):
    if df.empty:
        return df.copy()

    scaler = StandardScaler()
    standardized_values = scaler.fit_transform(df)

    df_standardized = pd.DataFrame(
        standardized_values,
        index=df.index,
        columns=df.columns
    )

    return df_standardized
